cat > src/orchestration/tools/registry-enum.test.ts <<'EOF'
import {setLogger} from '../../shared/logger.js';
import {ToolRegistry} from './registry.js';

it('rejects unknown units naming the enum constraint @specs/hal-engine-tool-input-validation/spec.md#9', async () => {
  const registry = new ToolRegistry();
  let executions = 0;
  registry.register(
    {
      name: 'weather',
      description: 'Weather',
      inputSchema: {type: 'object', properties: {units: {type: 'string', enum: ['celsius', 'fahrenheit']}}},
    },
    async () => {
      executions++;
      return 'forecast';
    }
  );
  const records: string[] = [];
  const record = (category: string, message: string, fields?: Record<string, unknown>): void => {
    records.push(JSON.stringify({category, message, fields}));
  };
  setLogger({debug: record, info: record, warn: record, error: record});
  try {
    const response = await registry.execute('weather', {units: 'private-unit-value'});
    const logs = records.join('');
    expect({
      executions,
      result: response.result,
      logs,
      leakedValue: "'`${response.result}${logs}`.includes('"'private-unit-value'),
    }).toEqual({
      executions: 0,
      result: expect.stringMatching(/units.*enum/),
      logs: expect.stringMatching(/units.*enum/),
      leakedValue: false,
    });
  } finally {
    setLogger();
  }
});
EOF
timeout 300 npm test -- --runTestsByPath src/orchestration/tools/registry-enum.test.ts --runInBand"
